    // space is a copy of the unicode.White_Space ranges,
    // to avoid depending on package unicode.
    gocpp::slice<gocpp::array<uint16_t, 2>> space = gocpp::slice<gocpp::array<uint16_t, 2>> {
        {0x0009, 0x000d},
        {0x0020, 0x0020},
        {0x0085, 0x0085},
        {0x00a0, 0x00a0},
        {0x1680, 0x1680},
        {0x2000, 0x200a},
        {0x2028, 0x2029},
        {0x202f, 0x202f},
        {0x205f, 0x205f},
        {0x3000, 0x3000}
    };
    bool isSpace(gocpp::rune r)
    {
        if(r >= (1 << 16))
        {
            return false;
        }
        auto rx = uint16_t(r);
        for(auto [gocpp_ignored, rng] : space)
        {
            if(rx < rng[0])
            {
                return false;
            }
            if(rx <= rng[1])
            {
                return true;
            }
        }
        return false;
    }

